const status=(s)=>{const map={PUBLISHED:'green',ACTIVE:'green',VERIFIED:'green',APPROVED:'green',SHORTLISTED:'purple',UNDER_REVIEW:'amber',SUBMITTED:'blue',DRAFT:'',CLOSED:'',AWARDED:'green',NOT_SELECTED:'red',PENDING:'amber',ANSWERED:'green',UNANSWERED:'amber'};const text=String(s).replaceAll('_',' ').toLowerCase().replace(/\b\w/g,c=>c.toUpperCase());return `<span class="status ${map[s]||''}">${text}</span>`};
