function orgProfile(){return `<div class="grid-2"><section class="panel"><div class="panel-header"><div><h2>Organization information</h2><p>These details appear on your published tenders.</p></div>${status('VERIFIED')}</div><div class="form-grid"><div class="field"><label>Legal organization name</label><input class="input" value="Department of Digital Services"></div><div class="field"><label>Organization type</label><input class="input" value="Private company"></div><div class="field"><label>Category</label><input class="input" value="Technology & Digital Services"></div><div class="field"><label>Location</label><input class="input" value="Chennai, Tamil Nadu"></div><div class="field field-full"><label>Organization description</label><textarea class="textarea">We deliver digital infrastructure and technology services to education, public-interest, and commercial organizations.</textarea></div><div class="field"><label>Procurement contact name</label><input class="input" value="Meera Krishnan"></div><div class="field"><label>Contact email</label><input class="input" value="procurement@digitalservices.example"></div></div><button class="button button-primary" style="margin-top:15px" data-action="save-profile">Save profile</button></section><aside><section class="panel"><h2 style="font:700 13px Manrope;margin:0 0 12px">Verification status</h2><div class="callout green"><strong>Verified organization</strong><br/>Approved 04 Sep 2026 · Verified badge appears on your published tenders.</div><div class="doc-row"><span class="doc-icon">PDF</span><div class="row-main"><strong>Certificate of Incorporation</strong><small>Verified by platform admin</small></div><span class="status green">Approved</span></div><button class="text-button" data-action="verification-detail">View verification record →</button></section><section class="panel"><h2 style="font:700 12px Manrope;margin:0 0 8px">Public profile preview</h2><p class="row-sub" style="line-height:1.6">See how suppliers will see your organization information and verification badge.</p><button class="button button-secondary button-small" data-action="public-preview">Preview public profile</button></section></aside></div>`}
function adminDashboard(){return `<div class="hero-card"><div class="hero-kicker">Platform health · 24 Oct 2026</div><h2>Good morning, Platform Admin</h2><p>Seven verification requests and two tender reports need attention. Review queues and moderation actions are recorded in the activity log.</p><div class="hero-actions"><button class="button button-primary" data-nav="verification">Review verification queue</button><button class="button button-secondary" data-nav="adminActivity">Activity log</button></div></div><div class="stat-grid">${stat('Pending verification','07','4 businesses · 3 organizations','✓')}${stat('Verified organizations','42','2 approved this week','♙')}${stat('Active tenders','128','Across 42 publishers','▤')}${stat('Reported content','02','Review moderation queue','⚑')}</div><div class="grid-2"><section class="panel"><div class="panel-header"><div><h2>Verification queue</h2><p>Oldest request has been waiting 4 days.</p></div><button class="section-link button-quiet" data-nav="verification">Open queue →</button></div>${[['SB','Sana Business Supplies','Business · 4 days ago'],['ET','Evergreen Technology','Organization · 2 days ago'],['MK','M.K. Fabrication','Business · Today']].map(x=>`<div class="list-row"><span class="person">${x[0]}</span><div class="row-main"><div class="row-title">${x[1]}</div><div class="row-sub">${x[2]}</div></div>${status('PENDING')}</div>`).join('')}</section><section class="panel"><div class="panel-header"><div><h2>Recent platform activity</h2><p>Administrative actions are auditable.</p></div><button class="section-link button-quiet" data-nav="adminActivity">View log →</button></div>${[['Verification approved','Meera Krishnan · Organization','Today, 10:42'],['Tender report submitted','TB-ORG-019 · Invalid contact','Today, 09:18'],['Category added','Healthcare Equipment','Yesterday, 16:07']].map(x=>`<div class="list-row"><span class="info-icon">◷</span><div class="row-main"><div class="row-title">${x[0]}</div><div class="row-sub">${x[1]}</div></div><div class="row-end"><small>${x[2]}</small></div></div>`).join('')}</section></div><section class="panel"><div class="panel-header"><div><h2>Platform safeguards</h2><p>Operational and security overview.</p></div></div><div class="grid-even"><div class="callout green"><strong>Role permissions active</strong><br/>Business, Organization, and Admin routes are separated.</div><div class="callout"><strong>Document storage protected</strong><br/>Private files require an authenticated, authorized request.</div></div></section>`}
function verification(){return `<div class="stat-grid">${stat('Awaiting review','07','4 business · 3 organization','◷')}${stat('Under review','03','Assigned to your team','⌕')}${stat('Approved this month','18','+4 over last month','✓')}${stat('Average review time','2.4 days','Target: within 7 days','◷')}</div><section class="panel"><div class="toolbar"><input class="input search" placeholder="⌕  Search applicant or registration no."/><select class="select"><option>All request types</option><option>Business</option><option>Organization</option></select><select class="select"><option>Pending</option><option>Under review</option><option>Approved</option><option>Rejected</option></select></div><div class="table-wrap"><table><thead><tr><th>Applicant</th><th>Type</th><th>Submitted</th><th>Documents</th><th>Status</th><th></th></tr></thead><tbody>${[['Sana Business Supplies','Business','20 Oct 2026','4 files'],['Evergreen Technology','Organization','22 Oct 2026','5 files'],['M.K. Fabrication','Business','24 Oct 2026','3 files'],['Apex Green Technologies','Business','19 Oct 2026','6 files']].map((r,i)=>`<tr><td><strong>${r[0]}</strong><small>REG-2026-00${149+i}</small></td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td>${status(i===3?'UNDER_REVIEW':'PENDING')}</td><td><button class="text-button" data-action="review-verification">Review →</button></td></tr>`).join('')}</tbody></table></div></section>`}
function genericAdmin(key){let title=titles[key][1];return `<section class="panel"><div class="panel-header"><div><h2>${title}</h2><p>This screen is included to guide future implementation against the proposed scope.</p></div><button class="button button-primary" data-action="generic-add">＋ Add new</button></div><div class="toolbar"><input class="input search" placeholder="⌕  Search records"/><select class="select"><option>All statuses</option><option>Active</option><option>Inactive</option></select></div><div class="callout">Reference UI only. Connect this screen to an authorized API and persistent audit records before treating it as a production feature.</div><div class="empty-state"><strong>Reference screen</strong>Use Antigravity to implement this view with backend permissions, input validation, and persistent data.</div></section>`}
const renderers={dashboard:businessDashboard,discover,tender,apply:applicationWizard,applications,saved,documents,partners,orgDashboard:organizationDashboard,orgTenders,createTender,applicants,faqs,orgUpdates:updates,orgResults,results,orgProfile,adminDashboard,verification};
function render(){renderNav();const key=appState.screen;document.querySelector('#breadcrumbs').innerHTML=`${appState.workspace==='business'?'Business':appState.workspace==='organization'?'Organization':'Admin'} workspace <span>/</span> ${(titles[key]?.[1]||'Overview')}`;const fn=renderers[key];content.innerHTML=heading(key)+(fn?fn():genericAdmin(key));document.querySelector('#user-role').textContent=appState.workspace==='business'?'Business account · Verified':appState.workspace==='organization'?'Organization account · Verified':'Platform administrator';document.querySelector('#user-name').textContent=appState.workspace==='business'?'Aarav Kumar':appState.workspace==='organization'?'Meera Krishnan':'Platform Admin';window.scrollTo({top:0,behavior:'smooth'});}
function go(key){appState.screen=key;const group=Object.keys(navConfig).find(w=>navConfig[w].some(g=>g[1].some(i=>i[0]===key)));if(group)appState.workspace=group;render();}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(appState.toastTimer);appState.toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function openModal(html){document.querySelector('#modal-content').innerHTML=html;document.querySelector('#modal').classList.add('open');document.querySelector('#modal').setAttribute('aria-hidden','false')}
function closeModal(){document.querySelector('#modal').classList.remove('open');document.querySelector('#modal').setAttribute('aria-hidden','true')}
document.addEventListener('click',e=>{const navLink=e.target.closest('[data-nav]');if(navLink){e.preventDefault();go(navLink.dataset.nav);return}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
 if(action==='save'){const ref=b.dataset.ref;if(appState.saved.has(ref)){appState.saved.delete(ref);toast('Removed from saved tenders.')}else{appState.saved.add(ref);toast('Tender saved to your list.')}render()}
 if(action==='review-application'){go('apply');openModal(`<h2 id="modal-title">Application review</h2><p>Review the submitted application snapshot before final confirmation.</p><div class="callout green"><strong>Ready to submit</strong><br/>4 required documents selected · All mandatory fields complete.</div><div class="list-row"><div class="row-main"><div class="row-title">Application reference</div><div class="row-sub">Assigned after final confirmation</div></div><span class="status blue">Preview</span></div><div class="modal-actions"><button class="button button-secondary" data-close>Continue editing</button><button class="button button-primary" data-action="submit-application">Confirm submission</button></div>`)}
 if(action==='submit-application'){closeModal();openModal(`<h2 id="modal-title">Submission confirmation</h2><p>Your prototype application has been submitted in this preview flow.</p><div class="callout green"><strong>APP-2026-0149</strong><br/>Supply of Computer Workstations · Submitted 24 Oct 2026 at 11:20 AM<br/>A preserved copy of the submitted details and document selections is associated with this reference.</div><p>This is a visual reference only. No real application was sent or stored.</p><div class="modal-actions"><button class="button button-primary" data-action="close-and-applications">View application tracker</button></div>`)}
 if(action==='close-and-applications'){closeModal();go('applications');toast('Showing the application tracker reference screen.')}
 if(action==='ask-question'){openModal(`<h2 id="modal-title">Ask a tender clarification</h2><p>Your question is sent to the organization and may be published for all interested suppliers.</p><div class="field"><label>Question</label><textarea class="textarea" placeholder="Ask a clear question about a requirement…"></textarea></div><div class="modal-actions"><button class="button button-secondary" data-close>Cancel</button><button class="button button-primary" data-action="send-question">Submit question</button></div>`)}
 if(action==='send-question'){closeModal();toast('Question added to the prototype clarification queue.')}
 if(action==='publish-faq'){const answer=document.querySelector('#faq-answer')?.value?.trim();if(!answer){toast('Write an answer before publishing.');return}appState.faqs.unshift({q:'Can a supplier propose an equivalent workstation model?',a:answer,by:'Digital Services team',date:'24 Oct 2026',status:'Answered'});render();toast('Clarification published in the prototype.')}
 if(action==='save-faq-draft'){toast('FAQ response saved as a draft in this preview.')}
 if(action==='add-faq'||action==='edit-faq'){openModal(`<h2 id="modal-title">${action==='add-faq'?'Add official FAQ':'Edit published answer'}</h2><p>FAQs are associated with a tender and published to all suppliers.</p><div class="field"><label>Question</label><input class="input" style="width:100%" placeholder="Enter the question"></div><div class="field" style="margin-top:10px"><label>Answer</label><textarea class="textarea" placeholder="Enter the official answer"></textarea></div><div class="modal-actions"><button class="button button-secondary" data-close>Cancel</button><button class="button button-primary" data-action="save-generic">Save FAQ</button></div>`)}
 if(action==='review-applicant'){const a=appState.applicants[Number(b.dataset.index)||0];openModal(`<h2 id="modal-title">Review applicant</h2><p>${a.company} · Application APP-2026-0142</p><div class="grid-even"><div class="surface"><span class="mini-label">Business</span><div class="row-title">${a.company}</div><div class="row-sub">${a.category} · ${a.location}</div></div><div class="surface"><span class="mini-label">Preliminary eligibility</span><div class="row-title">Potentially eligible</div><div class="row-sub">Review documents and evidence manually.</div></div></div><h3 style="font-size:11px">Submitted documents</h3>${['GST Registration Certificate','Company Registration','Turnover Statement','ISO 9001 Certificate'].map(d=>`<div class="doc-row"><span class="doc-icon">PDF</span><div class="row-main"><strong>${d}</strong><small>Submitted 12 Oct 2026</small></div><button class="text-button" data-action="view-file">View</button></div>`).join('')}<div class="field" style="margin-top:12px"><label>Internal review note (not shared with applicant)</label><textarea class="textarea" placeholder="Add a note for your evaluation team"></textarea></div><div class="modal-actions"><button class="button button-secondary" data-close>Close</button><button class="button button-secondary" data-action="set-app-status" data-status="UNDER_REVIEW">Under review</button><button class="button button-primary" data-action="set-app-status" data-status="SHORTLISTED">Shortlist</button></div>`)}
 if(action==='set-app-status'){closeModal();toast(`Applicant status updated to ${b.dataset.status.replace('_',' ').toLowerCase()} in this preview.`)}
 if(action==='review-verification'){openModal(`<h2 id="modal-title">Verification review</h2><p>Sana Business Supplies · Business account · Submitted 20 Oct 2026</p><div class="callout">Review the submitted registration and financial documents. Approval displays a verified badge on the business profile.</div><div class="doc-row"><span class="doc-icon">PDF</span><div class="row-main"><strong>Business registration certificate</strong><small>Uploaded 20 Oct · File type validated</small></div><button class="text-button">View</button></div><div class="doc-row"><span class="doc-icon">PDF</span><div class="row-main"><strong>GST certificate</strong><small>Uploaded 20 Oct · File type validated</small></div><button class="text-button">View</button></div><div class="modal-actions"><button class="button button-danger" data-action="verification-decision" data-status="REJECTED">Reject</button><button class="button button-primary" data-action="verification-decision" data-status="APPROVED">Approve & verify</button></div>`)}
 if(action==='verification-decision'){closeModal();toast(`Verification ${b.dataset.status.toLowerCase()} in the prototype.`)}
 if(action==='publish'){openModal(`<h2 id="modal-title">Publish tender</h2><p>Before publishing, confirm that the notice and requirements have been reviewed.</p><div class="checkline"><span class="check">✓</span><span>Required details and deadline are complete.</span></div><div class="checkline"><span class="check">✓</span><span>Eligibility and document requirements have been checked against the notice.</span></div><div class="modal-actions"><button class="button button-secondary" data-close>Keep as draft</button><button class="button button-primary" data-action="publish-confirm">Confirm publication</button></div>`)}
 if(action==='publish-confirm'){closeModal();toast('Tender published in prototype preview.')}
 if(action==='save-draft'){toast('Tender draft saved in this preview.');}
 if(action==='review-tender'){openModal(`<h2 id="modal-title">Review before publishing</h2><p>Check extraction and manually supplied information against the official tender notice.</p><div class="callout amber"><strong>1 item needs confirmation:</strong> project duration was not found in the uploaded PDF.</div><div class="checkline"><span class="check">✓</span><span>Title, category, value, deadline and eligibility entered.</span></div><div class="checkline"><span class="check">✓</span><span>Required documents are listed.</span></div><div class="modal-actions"><button class="button button-secondary" data-close>Edit details</button><button class="button button-primary" data-action="publish-confirm">Confirm & publish</button></div>`)}
 if(action==='toggle-enrollment'){appState.partnerOptIn=!appState.partnerOptIn;render();toast(appState.partnerOptIn?'Your sample profile is opted into the directory.':'Directory opt-in turned off in preview.')}
 if(action==='save-partner'){b.textContent=b.textContent.includes('Saved')?'♡ Save partner':'♥ Saved';toast('Partner saved in the preview.')}
 if(action==='upload-doc'||action==='upload-tender'){openModal(`<h2 id="modal-title">Upload a document</h2><p>Choose a PDF or image file. Production implementation must validate type, size, ownership, and access permissions.</p><div class="file-drop"><div class="upload-icon">⇧</div><strong>Choose a file to upload</strong><small>PDF, JPG or PNG · Max 8 MB for this prototype reference</small><input type="file" style="margin:12px auto 0;max-width:230px" accept=".pdf,.jpg,.jpeg,.png"></div><div class="field" style="margin-top:12px"><label>Document type</label><select class="select" style="width:100%"><option>Choose type</option><option>Registration</option><option>Financial</option><option>Certification</option><option>Experience</option></select></div><div class="modal-actions"><button class="button button-secondary" data-close>Cancel</button><button class="button button-primary" data-action="upload-confirm">Add to vault</button></div>`)}
 if(action==='upload-confirm'){closeModal();toast('File selected for the reference flow; not uploaded to a server.')}
 if(action==='filters'){openModal(`<h2 id="modal-title">More tender filters</h2><p>Narrow opportunities by tender details and your preliminary eligibility.</p><div class="form-grid"><div class="field"><label>Estimated value</label><select class="select" style="width:100%"><option>Any value</option><option>Under ₹10 lakh</option><option>₹10–50 lakh</option><option>Above ₹50 lakh</option></select></div><div class="field"><label>Eligibility status</label><select class="select" style="width:100%"><option>Any status</option><option>Eligible</option><option>Potentially eligible</option></select></div><div class="field"><label>Tender type</label><select class="select" style="width:100%"><option>Products and services</option><option>Products</option><option>Services</option></select></div><div class="field"><label>Publisher verification</label><select class="select" style="width:100%"><option>All publishers</option><option>Verified only</option></select></div></div><div class="modal-actions"><button class="button button-secondary" data-close>Cancel</button><button class="button button-primary" data-close>Apply filters</button></div>`)}
 if(action==='application-detail'||action==='result-detail'){openModal(`<h2 id="modal-title">${action==='result-detail'?'Tender outcome':'Application details'}</h2><p>Campus Laptop Refresh · TB-ORG-009</p><div class="callout"><strong>Application APP-2026-0084</strong><br/>Submitted 27 Sep 2026 · Decision published 10 Oct 2026.</div><div class="timeline"><div class="timeline-step done"><span class="bubble">✓</span>Submitted</div><div class="timeline-line done"></div><div class="timeline-step done"><span class="bubble">✓</span>Under review</div><div class="timeline-line done"></div><div class="timeline-step current"><span class="bubble">•</span>Result</div></div><p>Outcome: Not selected. The organization published the result for this tender. Contact the publisher through the clarification channel if additional feedback is available.</p><div class="modal-actions"><button class="button button-primary" data-close>Close</button></div>`)}
 if(action==='publish-result'){openModal(`<h2 id="modal-title">Publish tender result</h2><p>Campus Network Upgrade · TB-ORG-014 · 9 applications</p><div class="field"><label>Outcome</label><select class="select" style="width:100%"><option>Awarded</option><option>No award</option><option>Cancelled</option></select></div><div class="field" style="margin-top:10px"><label>Selected business (if disclosure is permitted)</label><select class="select" style="width:100%"><option>Select evaluated applicant</option><option>Kumar Digital Systems</option><option>Pinnacle Systems</option></select></div><div class="field" style="margin-top:10px"><label>Decision summary</label><textarea class="textarea" placeholder="Provide a short, publishable outcome summary"></textarea></div><div class="modal-actions"><button class="button button-secondary" data-close>Save draft</button><button class="button button-primary" data-action="publish-result-confirm">Publish outcome</button></div>`)}
 if(action==='publish-result-confirm'){closeModal();toast('Outcome published in the preview only.')}
 if(action==='notify-applicants'){toast('Affected applicants notified in the preview.')}
 if(action==='history'){openModal(`<h2 id="modal-title">Tender version history</h2><p>Historical changes remain visible to users who saved or applied to the tender.</p><div class="list-row"><div class="row-main"><div class="row-title">Version 2 · Published 14 Oct 2026</div><div class="row-sub">Deadline, turnover and certification updated</div></div><span class="status green">Current</span></div><div class="list-row"><div class="row-main"><div class="row-title">Version 1 · Published 08 Oct 2026</div><div class="row-sub">Initial publication</div></div><button class="text-button">Compare</button></div>`)}
 if(action==='save-profile'){toast('Profile updated in this preview.')}
 if(action==='generic-add'){toast('This reference view is ready for implementation.')}
 if(action==='export'){toast('Applicant export is a design reference; no file generated.')}
 if(action==='refresh'){toast('Reference data refreshed.')}
 if(action==='doc-menu'){toast('Document actions: preview, replace, or remove.')}
 if(action==='edit-tender'){go('createTender');toast('Editing an existing tender reference.')}
 if(action==='save-generic'){closeModal();toast('Saved in prototype preview.')}
 if(action==='verification-detail'||action==='public-preview'||action==='extraction-details'){toast('Detail view shown as a future implementation reference.')}
 if(action==='view-file'){toast('Private document preview requires authorized backend storage.')}
});
document.addEventListener('click',e=>{if(e.target.matches('[data-close]'))closeModal()});
document.querySelector('#modal-close').addEventListener('click',closeModal);document.querySelector('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});document.querySelector('#workspace').addEventListener('change',e=>{appState.workspace=e.target.value;appState.screen=appState.workspace==='business'?'dashboard':appState.workspace==='organization'?'orgDashboard':'adminDashboard';render()});document.querySelector('#dismiss-alert').addEventListener('click',()=>document.querySelector('.demo-alert').remove());
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
render();
